type SchoolProgram = { id: string; name: string; code: string; level: "SMK"; active?: boolean };
type Subject = { id: string; name: string; code: string; defaultWeeklyPeriods?: number; curriculumYear?: string; curriculumProfileId?: string; group?: string; isElective?: boolean; requirement?: "required" | "elective"; active?: boolean; level?: SchoolProfile["level"]; gradeNames?: string[]; classIds?: string[]; programIds?: string[] };
